/**
 * The app icon as used inside the app. From 32 px up the strokes get their soft glow. With `blink`
 * the _ cursor blinks like a terminal cursor (`.sh-brand-cursor` in shell.css).
 */
export default function BrandMark({ size, blink = false }: { size: number; blink?: boolean }) {
  const id = useId().replace(/:/g, "");
  const cursorClass = blink ? "sh-brand-cursor" : undefined;
  const small = size < 32;
  const glyph = (extra: object) => (
    <g fill="none" stroke={`url(#${id}-au)`} strokeLinecap="round" strokeLinejoin="round" {...extra}>
      <path d="M32 34 L62 60 L32 86" strokeWidth={small ? 18 : 16} />
      <path d="M70 86 H92" strokeWidth={small ? 18 : 16} className={cursorClass} />
    </g>
  );

  return (
    <svg width={size} height={size} viewBox="0 0 120 120" aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id={`${id}-tile`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#16162A" />
          <stop offset="1" stopColor="#05050C" />
        </linearGradient>
        <radialGradient id={`${id}-tg`} cx=".3" cy=".18" r=".9">
          <stop offset="0" stopColor="#8B5CF6" stopOpacity=".35" />
          <stop offset="1" stopColor="#8B5CF6" stopOpacity="0" />
        </radialGradient>
        <linearGradient id={`${id}-au`} x1="30" y1="30" x2="94" y2="92" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#22D3EE" />
          <stop offset=".5" stopColor="#818CF8" />
          <stop offset="1" stopColor="#F472B6" />
        </linearGradient>
        <filter id={`${id}-bl`} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation="6" />
        </filter>
      </defs>
      <rect width="120" height="120" rx="27" fill={`url(#${id}-tile)`} />
      <rect width="120" height="120" rx="27" fill={`url(#${id}-tg)`} />
      <rect x=".7" y=".7" width="118.6" height="118.6" rx="26.3" fill="none" stroke="#FFFFFF" strokeOpacity=".14" strokeWidth="1.4" />
      <g transform={`translate(60 60) scale(${small ? 0.86 : 0.78}) translate(-62 -60)`}>
        {!small && glyph({ filter: `url(#${id}-bl)`, opacity: 0.7 })}
        {glyph({})}
      </g>
    </svg>
  );
}

/** "Shellium" in the brand typeface (outlines), colored by the surrounding text color. */
export function BrandWordmark({ height }: { height: number }) {
  return (
    <svg width={Math.round(height * 5.0592)} height={height} viewBox="-1 14.55 259.13 51.22" role="img" aria-label="Shellium">
      <path d={BRAND_WORDMARK_PATH} fill="currentColor" />
    </svg>
  );
}
